mapper.select:
SELECT r.* FROM qt_user_responses r
WHERE r.qt_content_id = #{qtContentId}
ORDER BY r.created_at ASC

mapper.insert:
INSERT INTO qt_user_responses(id, user_id, qt_content_id, meditation, application, prayer, photos, visibility)
VALUES(#{id}, #{userId}, #{qtContentId}, #{meditation}, #{application}, #{prayer}, #{photos},

           #{visibility}
           'PUBLIC'
       )

mapper.select:
SELECT r.* FROM qt_user_responses r
WHERE r.user_id = #{userId}
ORDER BY r.created_at DESC
LIMIT #{size} OFFSET #{offset}
